import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

maxred_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor max_reduce_dim(torch::Tensor x, int64_t dim);
"""

maxred_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Max-reduction over the middle dimension of a contiguous 3D tensor [B, R, N].
// Output shape: [B, N]. Optimization: split the R reduction across 8 threads
// per output column (32 columns x 8 R-slices per 256-thread block), then do a
// small shared-memory reduction across the 8 partial maxima.
template <typename T, int RSLICES>
__global__ void max_reduce_middle_kernel(const T* __restrict__ X,
                                         T* __restrict__ Y,
                                         int B, int R, int N)
{
  constexpr int Cols = 32;
  const int tx  = threadIdx.x;
  const int ty  = threadIdx.y;
  const int b   = blockIdx.y;
  const int col = blockIdx.x * Cols + tx;
  // CuTe tensor views for this batch slice
  Tensor mX = make_tensor(make_gmem_ptr(X + (int64_t)b * R * N),
                          make_shape(R, N),
                          make_stride(N, Int<1>{}));
  Tensor mY = make_tensor(make_gmem_ptr(Y + (int64_t)b * N),
                          make_shape(N),
                          make_stride(Int<1>{}));
  const T neg_inf = -std::numeric_limits<T>::infinity();
  T acc0 = neg_inf, acc1 = neg_inf, acc2 = neg_inf, acc3 = neg_inf;
  if (col < N) {
    int r = ty;
    // Each R-slice keeps 4 independent accumulators while striding by RSLICES.
    for (; r + 3 * RSLICES < R; r += 4 * RSLICES) {
      acc0 = ::max(acc0, mX(r,               col));
      acc1 = ::max(acc1, mX(r +     RSLICES, col));
      acc2 = ::max(acc2, mX(r + 2 * RSLICES, col));
      acc3 = ::max(acc3, mX(r + 3 * RSLICES, col));
    }
    for (; r < R; r += RSLICES) {
      acc0 = ::max(acc0, mX(r, col));
    }
  }
  acc0 = ::max(acc0, acc1);
  acc2 = ::max(acc2, acc3);
  acc0 = ::max(acc0, acc2);
  __shared__ T smem[RSLICES][Cols];
  smem[ty][tx] = acc0;
  __syncthreads();
  if (ty == 0 && col < N) {
    T v = smem[0][tx];
    #pragma unroll
    for (int u = 1; u < RSLICES; ++u) {
      v = ::max(v, smem[u][tx]);
    }
    mY(col) = v;
  }
}

torch::Tensor max_reduce_dim(torch::Tensor x, int64_t dim) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(x.dim() == 3, "x must be 3D [B, R, N]");

  if (dim < 0) dim += x.dim();
  TORCH_CHECK(dim == 1, "custom kernel currently reduces over dim == 1");

  auto x_c = x.contiguous();

  const int64_t B = x_c.size(0);
  const int64_t R = x_c.size(1);
  const int64_t N = x_c.size(2);

  auto y = torch::empty({B, N}, x_c.options());

  constexpr int Cols    = 32;
  constexpr int RSlices = 8;
  dim3 block(Cols, RSlices);
  dim3 grid((unsigned)((N + Cols - 1) / Cols), (unsigned)B);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  max_reduce_middle_kernel<float, RSlices><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      y.data_ptr<float>(),
      (int)B, (int)R, (int)N);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "max_reduce_middle_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

maxred_ext = load_inline(
    name="cute_max_reduce_ext",
    cpp_sources=maxred_cpp_decl,
    cuda_sources=maxred_cuda_src,
    functions=["max_reduce_dim"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Max reduction over a specific dimension, implemented with a single custom
    CUDA kernel written with CuTe tensors/layouts.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self._ext = maxred_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.max_reduce_dim(x, self.dim)

