// Max-reduction over the middle dimension of a contiguous 3D tensor [B, R, N].
// Output shape: [B, N]. Each thread computes one output element: max over R
// values strided by N (coalesced across threads along N).
// ILP: 4 independent accumulators, inner loop unrolled by 4.
template <typename T, int UNROLL>
__global__ void max_reduce_middle_kernel(const T* __restrict__ X,
                                         T* __restrict__ Y,
                                         int B, int R, int N)
{
  const int b   = blockIdx.y;
  const int col = blockIdx.x * blockDim.x + threadIdx.x;
  if (col >= N) return;

  // CuTe tensor views for this batch slice
  Tensor mX = make_tensor(make_gmem_ptr(X + (int64_t)b * R * N),
                          make_shape(R, N),
                          make_stride(N, Int<1>{}));
  Tensor mY = make_tensor(make_gmem_ptr(Y + (int64_t)b * N),
                          make_shape(N),
                          make_stride(Int<1>{}));

  T acc[UNROLL];
  #pragma unroll
  for (int u = 0; u < UNROLL; ++u) {
    acc[u] = -std::numeric_limits<T>::infinity();
  }

  int r = 0;
  // Unrolled main loop with independent accumulators for ILP
  for (; r + UNROLL <= R; r += UNROLL) {
    #pragma unroll
    for (int u = 0; u < UNROLL; ++u) {
      acc[u] = ::max(acc[u], mX(r + u, col));
    }
  }
  // Tail
  for (; r < R; ++r) {
    acc[0] = ::max(acc[0], mX(r, col));
  }

  // Final tree reduction of accumulators
  #pragma unroll
  for (int u = 1; u < UNROLL; ++u) {
    acc[0] = ::max(acc[0], acc[u]);
  }

  mY(col) = acc[0];
}

